object Solution {
  def maxSizeSlices(slices: Array[Int]): Int = {
    val n = slices.length / 3

    // Helper function to solve the problem for a linear array (not circular)
    // We want to pick n slices from slices[l..r] with no two adjacent slices chosen
    def maxSumLinear(arr: Array[Int], n: Int): Int = {
      val length = arr.length
      // dp(i)(j): max sum picking j slices from first i slices (0-based)
      // with no two adjacent chosen
      val dp = Array.ofDim[Int](length + 1, n + 1)
      for (i <- 1 to length) {
        for (j <- 1 to n) {
          // Not pick current slice i-1
          val notPick = dp(i - 1)(j)
          // Pick current slice i-1, then previous slice i-2 cannot be chosen
          val pick = if (i >= 2) dp(i - 2)(j - 1) + arr(i - 1) else arr(i - 1)
          dp(i)(j) = math.max(notPick, pick)
        }
      }
      dp(length)(n)
    }

    // Because the pizza is circular, we cannot pick both first and last slice.
    // So we solve twice:
    // 1) exclude last slice, consider slices[0..length-2]
    // 2) exclude first slice, consider slices[1..length-1]
    // Take max of both.
    val case1 = maxSumLinear(slices.slice(0, slices.length - 1), n)
    val case2 = maxSumLinear(slices.slice(1, slices.length), n)
    math.max(case1, case2)
  }
}

